VALUES
  ('sd-mat-01', 'SD', 'small', 'Matematika', 'Operasi Hitung', 'easy', 'Hasil dari 125 + 240 - 65 adalah...', '["290","300","310","320"]'::jsonb, 1, '125 + 240 = 365, kemudian 365 - 65 = 300.'),
  ('sd-mat-02', 'SD', 'small', 'Matematika', 'Perkalian', 'easy', 'Di dalam sebuah kotak terdapat 12 pensil. Jika Ibu membeli 6 kotak pensil, jumlah seluruh pensil adalah...', '["60","64","72","84"]'::jsonb, 2, 'Jumlah seluruh pensil = 6 × 12 = 72 pensil.'),
  ('sd-mat-03', 'SD', 'small', 'Matematika', 'Pembagian', 'easy', 'Sebanyak 96 permen dibagikan sama rata kepada 8 anak. Setiap anak memperoleh...', '["10 permen","11 permen","12 permen","14 permen"]'::jsonb, 2, '96 dibagi 8 sama dengan 12 permen per anak.'),
  ('sd-mat-04', 'SD', 'small', 'Matematika', 'Bangun Datar', 'easy', 'Keliling sebuah persegi yang memiliki panjang sisi 9 cm adalah...', '["18 cm","27 cm","36 cm","81 cm"]'::jsonb, 2, 'Keliling persegi = 4 × sisi = 4 × 9 = 36 cm.'),
  ('sd-mat-05', 'SD', 'small', 'Matematika', 'Bangun Datar', 'medium', 'Luas persegi panjang dengan panjang 14 cm dan lebar 6 cm adalah...', '["20 cm²","40 cm²","74 cm²","84 cm²"]'::jsonb, 3, 'Luas persegi panjang = panjang × lebar = 14 × 6 = 84 cm².'),
  ('sd-mat-06', 'SD', 'small', 'Matematika', 'Pecahan', 'medium', 'Hasil dari 1/2 + 1/4 adalah...', '["2/6","3/4","2/4","1/8"]'::jsonb, 1, 'Samakan penyebut menjadi 4: 2/4 + 1/4 = 3/4.'),
  ('sd-mat-07', 'SD', 'small', 'Matematika', 'Satuan Waktu', 'easy', '2 jam + 35 menit sama dengan berapa menit?', '["120 menit","135 menit","155 menit","165 menit"]'::jsonb, 2, '2 jam = 2 × 60 = 120 menit. Jadi 120 + 35 = 155 menit.'),
  ('sd-mat-08', 'SD', 'small', 'Matematika', 'Satuan Panjang', 'easy', 'Panjang pita Rina 3 meter lebih 45 cm. Panjang pita tersebut dalam satuan cm adalah...', '["305 cm","345 cm","435 cm","3450 cm"]'::jsonb, 1, '3 meter = 300 cm, maka 300 cm + 45 cm = 345 cm.'),
  ('sd-mat-09', 'SD', 'small', 'Matematika', 'Sudut', 'easy', 'Besar sudut siku-siku adalah...', '["45°","60°","90°","180°"]'::jsonb, 2, 'Sudut siku-siku memiliki besar tepat 90 derajat.'),
  ('sd-mat-10', 'SD', 'small', 'Matematika', 'KPK & FPB', 'medium', 'Kelipatan Persekutuan Terkecil (KPK) dari 6 dan 8 adalah...', '["12","18","24","48"]'::jsonb, 2, 'Kelipatan 6: 6, 12, 18, 24. Kelipatan 8: 8, 16, 24. KPK terkecil yang sama adalah 24.'),
  ('sd-mat-11', 'SD', 'small', 'Matematika', 'Bilangan Prima', 'medium', 'Manakah di antara bilangan berikut yang merupakan bilangan prima?', '["9","15","17","21"]'::jsonb, 2, '17 hanya habis dibagi oleh 1 dan dirinya sendiri, sehingga 17 adalah bilangan prima.'),
  ('sd-mat-12', 'SD', 'small', 'Matematika', 'Satuan Berat', 'easy', '2 kg + 500 gram sama dengan berapa gram?', '["700 gram","1.500 gram","2.500 gram","25.000 gram"]'::jsonb, 2, '1 kg = 1.000 gram, sehingga 2 kg = 2.000 gram. 2.000 + 500 = 2.500 gram.'),
  ('sd-mat-13', 'SD', 'bonus', 'Matematika', 'Uang & Belanja', 'easy', 'Budi membeli buku Rp14.500 dan membayar dengan uang Rp20.000. Uang kembalian Budi adalah...', '["Rp4.500","Rp5.500","Rp6.500","Rp5.000"]'::jsonb, 1, 'Rp20.000 - Rp14.500 = Rp5.500.'),
