  ('sd-mat-15', 'SD', 'small', 'Matematika', 'Persen', 'medium', 'Bentuk persen dari pecahan 3/4 adalah...', '["25%","50%","75%","80%"]'::jsonb, 2, '3/4 × 100% = 75%.'),
  ('sd-mat-16', 'SD', 'small', 'Matematika', 'Desimal', 'easy', 'Hasil dari 2,5 + 1,75 adalah...', '["3,25","4,15","4,25","4,35"]'::jsonb, 2, '2,50 + 1,75 = 4,25.'),
  ('sd-mat-17', 'SD', 'large', 'Matematika', 'Volume Balok', 'hard', 'Sebuah akuarium berbentuk balok berukuran panjang 40 cm, lebar 25 cm, dan tinggi 30 cm. Volume air penuh akuarium tersebut dalam liter adalah...', '["20 liter","25 liter","30 liter","35 liter"]'::jsonb, 2, 'Volume = 40 × 25 × 30 = 30.000 cm³. Karena 1 liter = 1.000 cm³, volumenya 30 liter.'),
  ('sd-mat-18', 'SD', 'large', 'Matematika', 'Kecepatan & Jarak', 'hard', 'Ayah mengendarai sepeda motor dengan kecepatan rata-rata 50 km/jam selama 2 jam 30 menit. Jarak yang ditempuh Ayah adalah...', '["100 km","115 km","125 km","150 km"]'::jsonb, 2, '2 jam 30 menit = 2,5 jam. Jarak = 50 × 2,5 = 125 km.'),
  ('sd-mat-19', 'SD', 'large', 'Matematika', 'FPB Soal Cerita', 'hard', 'Ibu memiliki 24 kue coklat dan 36 kue keju yang akan dimasukkan ke dalam piring dengan jumlah sama banyak. Jumlah piring terbanyak yang dibutuhkan adalah...', '["6 piring","8 piring","12 piring","18 piring"]'::jsonb, 2, 'FPB dari 24 dan 36 adalah 12, sehingga paling banyak diperlukan 12 piring.'),
  ('sd-mat-20', 'SD', 'large', 'Matematika', 'Rata-rata', 'hard', 'Nilai ulangan Matematika Siti berturut-turut adalah 80, 90, 75, 85, dan 95. Nilai rata-rata ulangan Siti adalah...', '["82","84","85","86"]'::jsonb, 2, 'Jumlah nilai = 80 + 90 + 75 + 85 + 95 = 425. Rata-rata = 425 : 5 = 85.'),
