  ('smp-mat-01', 'SMP', 'small', 'Matematika', 'Bilangan Bulat', 'easy', 'Hasil dari (-15) + 8 × (-3) adalah...', '["21","-39","-9","39"]'::jsonb, 1, 'Dahulukan perkalian: 8 × (-3) = -24. Lalu -15 + (-24) = -39.'),
  ('smp-mat-02', 'SMP', 'small', 'Matematika', 'Aljabar', 'easy', 'Bentuk sederhana dari 4x + 7y - 2x + 3y adalah...', '["2x + 10y","6x + 10y","2x + 4y","6x + 4y"]'::jsonb, 0, 'Gabungkan suku sejenis: (4x - 2x) + (7y + 3y) = 2x + 10y.'),
  ('smp-mat-03', 'SMP', 'small', 'Matematika', 'PLSV', 'easy', 'Jika 5x - 8 = 17, maka nilai dari x + 4 adalah...', '["5","8","9","11"]'::jsonb, 2, '5x = 25 sehingga x = 5. Maka x + 4 = 5 + 4 = 9.'),
  ('smp-mat-04', 'SMP', 'small', 'Matematika', 'Teorema Pythagoras', 'medium', 'Sebuah segitiga siku-siku memiliki panjang sisi siku-siku 6 cm dan 8 cm. Panjang sisi miring (hipotenusa) adalah...', '["10 cm","12 cm","14 cm","48 cm"]'::jsonb, 0, 'c = √(6² + 8²) = √(36 + 64) = √100 = 10 cm.'),
  ('smp-mat-05', 'SMP', 'small', 'Matematika', 'Lingkaran', 'medium', 'Keliling lingkaran dengan jari-jari 14 cm (π = 22/7) adalah...', '["44 cm","88 cm","154 cm","616 cm"]'::jsonb, 1, 'Keliling = 2 × π × r = 2 × (22/7) × 14 = 88 cm.'),
  ('smp-mat-06', 'SMP', 'small', 'Matematika', 'Perbandingan', 'easy', 'Perbandingan kelereng Adi dan Beno adalah 3 : 5. Jika jumlah kelereng mereka 40 butir, banyak kelereng Beno adalah...', '["15","20","25","30"]'::jsonb, 2, 'Kelereng Beno = (5 / (3 + 5)) × 40 = (5/8) × 40 = 25 butir.'),
  ('smp-mat-07', 'SMP', 'small', 'Matematika', 'Aritmetika Sosial', 'medium', 'Sebuah tas berharga Rp200.000 mendapat diskon 25%. Harga tas yang harus dibayar setelah diskon adalah...', '["Rp125.000","Rp150.000","Rp160.000","Rp175.000"]'::jsonb, 1, 'Diskon = 25% × 200.000 = 50.000. Harga bayar = 200.000 - 50.000 = Rp150.000.'),
  ('smp-mat-08', 'SMP', 'small', 'Matematika', 'Himpunan', 'medium', 'Diketahui A = {2, 3, 5, 7} dan B = {1, 3, 5, 9}. Irisan A ∩ B adalah...', '["{1, 2, 3, 5, 7, 9}","{3, 5}","{2, 7}","{1, 9}"]'::jsonb, 1, 'Irisan (∩) memuat anggota yang sama-sama ada di himpunan A dan B, yaitu 3 dan 5.'),
  ('smp-mat-09', 'SMP', 'small', 'Matematika', 'Gradien Garis', 'medium', 'Gradien dari garis dengan persamaan y = 3x - 7 adalah...', '["-7","3","7","-3"]'::jsonb, 1, 'Pada persamaan y = mx + c, koefisien x (m) merupakan gradien. Jadi m = 3.'),
  ('smp-mat-10', 'SMP', 'small', 'Matematika', 'Peluang', 'easy', 'Sebuah dadu bersisi 6 dilempar satu kali. Peluang munculnya mata dadu genap adalah...', '["1/6","1/3","1/2","2/3"]'::jsonb, 2, 'Mata dadu genap ada 3 ({2, 4, 6}) dari 6 kemungkinan. Peluangnya 3/6 = 1/2.'),
  ('smp-mat-11', 'SMP', 'bonus', 'Matematika', 'Pola Bilangan', 'medium', 'Dua suku berikutnya dari barisan bilangan 2, 5, 9, 14, 20, ... adalah...', '["26, 33","27, 35","25, 31","28, 36"]'::jsonb, 1, 'Selisih antar suku bertambah 1 (+3, +4, +5, +6), jadi berikutnya +7 (27) dan +8 (35).'),
  ('smp-mat-12', 'SMP', 'small', 'Matematika', 'Sudut Garis Sejajar', 'medium', 'Besar sudut pelurus dari sudut 115° adalah...', '["55°","65°","75°","85°"]'::jsonb, 1, 'Dua sudut berpelurus berjumlah 180°. Pelurusnya = 180° - 115° = 65°.'),
  ('smp-mat-13', 'SMP', 'large', 'Matematika', 'SPLDV', 'hard', 'Diketahui sistem persamaan x + y = 10 dan x - y = 4. Nilai dari x × y adalah...', '["14","21","24","28"]'::jsonb, 1, 'Jumlahkan kedua persamaan: 2x = 14 → x = 7, sehingga y = 3. Maka x × y = 7 × 3 = 21.'),
  ('smp-mat-14', 'SMP', 'large', 'Matematika', 'Bangun Ruang Sisi Lengkung', 'hard', 'Sebuah tabung memiliki jari-jari alas 7 cm dan tinggi 10 cm (π = 22/7). Volume tabung tersebut adalah...', '["440 cm³","770 cm³","1.540 cm³","3.080 cm³"]'::jsonb, 2, 'Volume tabung = π × r² × t = (22/7) × 7² × 10 = 154 × 10 = 1.540 cm³.'),
  ('smp-mat-15', 'SMP', 'large', 'Matematika', 'Fungsi Linear', 'hard', 'Fungsi f(x) = 3x - 5. Jika f(a) = 13, maka nilai a adalah...', '["4","5","6","7"]'::jsonb, 2, '3a - 5 = 13 → 3a = 18 → a = 6.'),
  ('smp-mat-16', 'SMP', 'large', 'Matematika', 'Persamaan Kuadrat Sederhana', 'hard', 'Himpunan penyelesaian dari x² - 9 = 0 adalah...', '["{-9, 9}","{-3, 3}","{0, 3}","{3}"]'::jsonb, 1, 'x² = 9 sehingga x = 3 atau x = -3.'),
  ('smp-bio-01', 'SMP', 'small', 'Biologi', 'Klasifikasi Makhluk Hidup', 'easy', 'Urutan tingkatan takson dari tertinggi ke terendah pada hewan yang benar adalah...', '["Kingdom - Filum - Kelas - Ordo - Famili - Genus - Spesies","Kingdom - Kelas - Filum - Ordo - Famili - Genus - Spesies","Spesies - Genus - Famili - Ordo - Kelas - Filum - Kingdom","Kingdom - Ordo - Kelas - Filum - Famili - Genus - Spesies"]'::jsonb, 0, 'Urutan takson hewan dimulai dari Kingdom, Filum, Kelas, Ordo, Famili, Genus, hingga Spesies.'),
  ('smp-bio-02', 'SMP', 'small', 'Biologi', 'Jaringan Tumbuhan', 'medium', 'Jaringan pengangkut pada tumbuhan yang bertugas menyalurkan hasil fotosintesis dari daun ke seluruh bagian tumbuhan adalah...', '["Xilem","Floem","Epidermis","Kambium"]'::jsonb, 1, 'Floem (pembuluh tapis) mengangkut hasil fotosintesis, sedangkan xilem mengangkut air dan mineral dari akar.'),
  ('smp-bio-03', 'SMP', 'small', 'Biologi', 'Sistem Pencernaan', 'easy', 'Asam klorida (HCl) dan enzim pepsin dihasilkan oleh organ...', '["Mulut","Kerongkongan","Lambung","Usus besar"]'::jsonb, 2, 'Dinding lambung menghasilkan HCl untuk membunuh kuman dan pepsin untuk memecah protein menjadi pepton.'),
  ('smp-bio-04', 'SMP', 'small', 'Biologi', 'Sistem Pernapasan', 'easy', 'Katup pangkal tenggorokan yang mencegah makanan masuk ke saluran pernapasan saat menelan adalah...', '["Faring","Epiglotis","Bronkiolus","Diafragma"]'::jsonb, 1, 'Epiglotis menutup saluran trakea saat kita menelan makanan.'),
  ('smp-bio-05', 'SMP', 'small', 'Biologi', 'Sistem Peredaran Darah', 'medium', 'Pembuluh darah yang membawa darah kaya oksigen keluar dari bilik kiri jantung ke seluruh tubuh adalah...', '["Vena kava","Arteri pulmonalis","Aorta","Vena pulmonalis"]'::jsonb, 2, 'Aorta adalah pembuluh arteri terbesar yang mengalirkan darah bersih dari bilik kiri ke seluruh tubuh.'),
  ('smp-bio-06', 'SMP', 'small', 'Biologi', 'Sistem Ekskresi', 'easy', 'Organ ekskresi manusia yang berfungsi menghasilkan cairan empedu dan menetralkan racun adalah...', '["Ginjal","Paru-paru","Hati","Kulit"]'::jsonb, 2, 'Hati berperan sebagai organ detoksifikasi racun serta menghasilkan empedu dari perombakan sel darah merah.'),
  ('smp-bio-07', 'SMP', 'small', 'Biologi', 'Ekosistem', 'easy', 'Jamur dan bakteri pengurai yang menguraikan sisa makhluk hidup menjadi zat anorganik disebut...', '["Produsen","Konsumen","Dekomposer","Detritivor"]'::jsonb, 2, 'Dekomposer (pengurai) memecah bahan organik mati menjadi unsur hara bagi tanah.'),
