  ('smp-bio-09', 'SMP', 'bonus', 'Biologi', 'Sel', 'easy', 'Bagian sel yang berfungsi mengendalikan seluruh aktivitas sel dan menyimpan materi genetik adalah...', '["Nukleus (Inti sel)","Vakuola","Sitoplasma","Membran sel"]'::jsonb, 0, 'Nukleus adalah pusat kendali sel yang berisi DNA.'),
  ('smp-bio-10', 'SMP', 'small', 'Biologi', 'Reproduksi Tumbuhan', 'medium', 'Perkembangbiakan vegetatif alami pada tumbuhan jahe dan kunyit menggunakan...', '["Umbi batang","Geragih","Rimpang (Rhizoma)","Tunas adventif"]'::jsonb, 2, 'Jahe, kunyit, dan lengkuas berkembang biak menggunakan rimpang (batang yang tumbuh menjalar di dalam tanah).'),
  ('smp-bio-11', 'SMP', 'large', 'Biologi', 'Pewarisan Sifat', 'hard', 'Persilangan antara tanaman berbunga ungu (UU) dan putih (uu) menghasilkan keturunan F1 seluruhnya ungu (Uu). Jika F1 disilangkan dengan sesamanya, persentase bunga putih pada F2 adalah...', '["0%","25%","50%","75%"]'::jsonb, 1, 'Uu × Uu menghasilkan UU (25%), Uu (50%), dan uu (25%). Jadi fenotipe putih (uu) sebesar 25%.'),
  ('smp-bio-12', 'SMP', 'large', 'Biologi', 'Hormon & Sistem Saraf', 'hard', 'Sel saraf yang berfungsi menghantarkan impuls dari alat indra menuju pusat saraf (otak dan sumsum tulang belakang) adalah...', '["Neuron motorik","Neuron sensorik","Neuron konektor","Akson"]'::jsonb, 1, 'Neuron sensorik (aferen) membawa rangsangan dari reseptor indra ke sistem saraf pusat.'),
