  ('smp-fis-02', 'SMP', 'small', 'Fisika', 'Massa Jenis', 'medium', 'Sebuah balok logam bermassa 400 gram memiliki volume 50 cm³. Massa jenis balok tersebut adalah...', '["4 g/cm³","8 g/cm³","10 g/cm³","20 g/cm³"]'::jsonb, 1, 'ρ = m / V = 400 g / 50 cm³ = 8 g/cm³.'),
  ('smp-fis-03', 'SMP', 'small', 'Fisika', 'Suhu & Termometer', 'easy', 'Suhu air 40°C jika diukur menggunakan termometer skala Reamur adalah...', '["32°R","40°R","50°R","72°R"]'::jsonb, 0, 'T(R) = (4/5) × T(C) = (4/5) × 40 = 32°R.'),
  ('smp-fis-04', 'SMP', 'small', 'Fisika', 'Hukum Newton', 'easy', 'Saat bus yang sedang melaju kencang tiba-tiba direm mendadak, tubuh penumpang terdorong ke depan. Peristiwa ini sesuai dengan...', '["Hukum I Newton (Inersia)","Hukum II Newton","Hukum III Newton","Hukum Archimedes"]'::jsonb, 0, 'Hukum I Newton menyatakan benda cenderung mempertahankan keadaan geraknya (kelembaman/inersia).'),
  ('smp-fis-05', 'SMP', 'small', 'Fisika', 'Usaha', 'medium', 'Gaya sebesar 30 N mendorong meja hingga berpindah sejauh 4 meter searah gaya. Usaha yang dilakukan gaya tersebut adalah...', '["7,5 J","34 J","120 J","240 J"]'::jsonb, 2, 'Usaha W = F × s = 30 N × 4 m = 120 Joule.'),
  ('smp-fis-06', 'SMP', 'small', 'Fisika', 'Pesawat Sederhana', 'easy', 'Gunting, jungkat-jungkit, dan linggis termasuk contoh pesawat sederhana jenis...', '["Katrol","Bidang miring","Tuas (pengungkit) golongan I","Roda berporos"]'::jsonb, 2, 'Pada tuas golongan I, titik tumpu berada di antara titik beban dan titik kuasa.'),
  ('smp-fis-07', 'SMP', 'small', 'Fisika', 'Tekanan', 'medium', 'Gaya tekan 120 N bekerja pada bidang seluas 0,4 m². Besar tekanan yang dihasilkan adalah...', '["48 Pa","120 Pa","300 Pa","480 Pa"]'::jsonb, 2, 'Tekanan P = F / A = 120 / 0,4 = 300 Pa (N/m²).'),
  ('smp-fis-08', 'SMP', 'small', 'Fisika', 'Getaran & Gelombang', 'medium', 'Sebuah bandul bergetar sebanyak 120 kali dalam waktu 1 menit. Frekuensi getaran bandul tersebut adalah...', '["0,5 Hz","2 Hz","60 Hz","120 Hz"]'::jsonb, 1, 'Frekuensi f = n / t = 120 getaran / 60 detik = 2 Hz.'),
  ('smp-fis-09', 'SMP', 'small', 'Fisika', 'Optik', 'easy', 'Sifat bayangan yang selalu dibentuk oleh cermin datar adalah...', '["Nyata, terbalik, diperkecil","Maya, tegak, sama besar","Maya, terbalik, diperbesar","Nyata, tegak, sama besar"]'::jsonb, 1, 'Cermin datar selalu menghasilkan bayangan maya, tegak, dan ukurannya sama dengan benda asli.'),
  ('smp-fis-10', 'SMP', 'bonus', 'Fisika', 'Listrik Statis', 'easy', 'Jika dua benda bermuatan listrik sejenis saling didekatkan, interaksi yang terjadi adalah...', '["Tarik-menarik","Tolak-menolak","Tidak ada gaya","Menetralkan diri"]'::jsonb, 1, 'Muatan sejenis (+ dengan + atau - dengan -) akan saling tolak-menolak.'),
  ('smp-fis-11', 'SMP', 'large', 'Fisika', 'Kalor', 'hard', 'Kalor yang diperlukan untuk memanaskan 2 kg air (c = 4.200 J/kg°C) dari suhu 20°C hingga 70°C adalah...', '["168.000 J","420.000 J","588.000 J","840.000 J"]'::jsonb, 1, 'Q = m · c · ΔT = 2 × 4.200 × (70 - 20) = 8.400 × 50 = 420.000 Joule.'),
  ('smp-fis-12', 'SMP', 'large', 'Fisika', 'Energi Listrik', 'hard', 'Sebuah setrika listrik berdaya 300 W dinyalakan selama 2 jam setiap hari. Energi listrik yang digunakan dalam 10 hari adalah...', '["3 kWh","6 kWh","12 kWh","60 kWh"]'::jsonb, 1, '300 W = 0,3 kW. Energi = 0,3 kW × 2 jam × 10 hari = 6 kWh.'),
  ('smp-fis-13', 'SMP', 'large', 'Fisika', 'Hukum Archimedes', 'hard', 'Gaya apung yang dialami suatu benda di dalam zat cair menurut Hukum Archimedes besarnya sama dengan...', '["Massa benda di udara","Berat zat cair yang dipindahkan oleh benda","Tekanan udara di permukaan","Volume wadah penampung air"]'::jsonb, 1, 'Hukum Archimedes menyatakan gaya ke atas (Fa) sama dengan berat zat cair yang dipindahkan oleh benda.'),
  ('smp-kim-01', 'SMP', 'small', 'Kimia', 'Unsur & Lambang', 'easy', 'Lambang kimia dari unsur Besi dan Emas berturut-turut adalah...', '["Be dan Em","Fe dan Au","Fe dan Ag","Cu dan Au"]'::jsonb, 1, 'Besi berasal dari kata Ferrum (Fe) dan Emas dari Aurum (Au), sedangkan Ag adalah Perak.'),
  ('smp-kim-02', 'SMP', 'small', 'Kimia', 'Perubahan Materi', 'easy', 'Manakah peristiwa berikut yang merupakan perubahan kimia?', '["Es batu mencair","Gula larut dalam air","Besi berkarat","Kertas dipotong kecil-kecil"]'::jsonb, 2, 'Besi berkarat menghasilkan zat baru (oksida besi) sehingga termasuk perubahan kimia.'),
  ('smp-kim-03', 'SMP', 'small', 'Kimia', 'Pemisahan Campuran', 'medium', 'Metode pemisahan campuran yang digunakan untuk memperoleh garam murni dari air laut melalui penguapan adalah...', '["Filtrasi","Kristalisasi","Kromatografi","Sentrifugasi"]'::jsonb, 1, 'Kristalisasi memisahkan zat padat terlarut (garam) dari pelarut cair dengan cara menguapkan airnya.'),
  ('smp-kim-04', 'SMP', 'small', 'Kimia', 'Asam Basa Garam', 'easy', 'Sifat larutan basa yang membedakannya dengan larutan asam adalah...', '["Berasa masam","Mengubah lakmus merah menjadi biru","Memiliki pH kurang dari 7","Bersifat korosif terhadap besi"]'::jsonb, 1, 'Larutan basa berasa pahit/licin, memiliki pH > 7, dan membirukan kertas lakmus merah.'),
