  ('smp-eng-01', 'SMP', 'small', 'Bahasa Inggris', 'Simple Past Tense', 'easy', 'Lengkapi kalimat: "Yesterday, Dimas ___ an ancient coin near the river."', '["find","finds","found","finding"]'::jsonb, 2, 'Keterangan waktu "Yesterday" menggunakan Simple Past Tense (V2 dari find adalah found).'),
