  ('smp-eng-08', 'SMP', 'bonus', 'Bahasa Inggris', 'Expressions', 'easy', 'Jika temanmu memenangkan lomba cerdas cermat, ungkapan yang tepat kamu ucapkan adalah...', '["I am sorry to hear that","Congratulations on your victory!","Never mind","Get well soon"]'::jsonb, 1, '"Congratulations" digunakan untuk memberi selamat atas keberhasilan seseorang.'),
  ('smp-eng-09', 'SMP', 'small', 'Bahasa Inggris', 'Countable & Uncountable', 'medium', '"How ___ water do we need for the long journey?"', '["many","much","few","several"]'::jsonb, 1, '"Water" adalah uncountable noun (benda tak terhitung), sehingga menggunakan "much".'),
  ('smp-eng-10', 'SMP', 'large', 'Bahasa Inggris', 'Descriptive Text', 'hard', 'Baca teks: "Crystal Cave is famous for its glowing blue walls and cool underground breeze. However, the narrow path makes it hard to cross without a lantern." Apa tujuan utama teks tersebut?', '["Menghibur pembaca dengan dongeng naga","Mendeskripsikan ciri-ciri Crystal Cave","Menceritakan pengalaman masa lalu penulis","Memberikan langkah membuat lentera"]'::jsonb, 1, 'Teks menggunakan Simple Present Tense untuk menggambarkan kondisi suatu tempat (Descriptive Text).'),
  ('smp-eng-11', 'SMP', 'large', 'Bahasa Inggris', 'Passive Voice Dasar', 'hard', 'Ubahlah ke kalimat pasif: "Sora unlocks the secret gate."', '["The secret gate is unlocked by Sora.","The secret gate was unlocked by Sora.","The secret gate unlocks by Sora.","The secret gate is unlocking by Sora."]'::jsonb, 0, 'Simple Present Passive menggunakan rumus is/am/are + V3 ("is unlocked").'),
